contract='''ROOT: D:/workspace/lemo-opuscar/films/horror-x-ep1-part1-60s. Read TREATMENT.md and WORKER-CONTRACT.md. Other agents work concurrently. Preserve their files. No recursive delegation, provider/account changes, paid calls, purchases, global installs or edits to original source episode/prototype. Use own native Orca task/dispatch to worker_done once then stop. Coordinator runs shell/browser validation; avoid optional commands if approvals block. Do not touch index.html, main.js, scene-kit.js or timeline.js. Account routing already selected; do not ask again.\n'''
tasks=[]
def task(tid,agent,outputs,body):
    brief=ROOT/'briefs'/f'{tid}.txt'
    brief.write_text(contract+'EXCLUSIVE OUTPUTS: '+', '.join(outputs)+'\n'+body+'\n',encoding='utf-8')
    tasks.append({'id':tid,'agent':agent,'outputs':outputs,'brief':str(brief),'status':'queued'})
